#!/usr/bin/env bash
# The files Claude may not change on its own: one table, read by guard.sh (Edit/Write) and
# guard-bash.sh (shell commands). Sourced, not run.
#
# `protection <path relative to the repo>` prints `deny|reason` or `ask|reason`, nothing when free.
# deny: never by hand (frozen, or generated by a command). ask: a guardrail; changing it is a
# decision the user approves, never a way to make a check pass.

protection() {
	case "$1" in
	legacy/python/*)
		echo 'deny|The legacy Python daemon is frozen (CLAUDE.md): never edit it.' ;;
	web/src/lib/api/generated.ts)
		echo "deny|Generated from the Rust wire types: change the Rust type and run \`just types\` (CLAUDE.md)." ;;
	backend/crates/gitprompt-core/tests/architecture/rules.rs)
		echo 'ask|The architecture map (layers, owned infrastructure crates, pure crates). Approve only a design change you agreed to, not a way around a failing check.' ;;
	backend/deny.toml)
		echo 'ask|The dependency policy (advisories, licenses, duplicate skips). A new skip or allowance is a decision: approve only with a reason naming the upstream crate.' ;;
	backend/clippy.toml | backend/rustfmt.toml | web/eslint.config.js | web/prettier.config.js | web/.prettierignore | web/tsconfig.json)
		echo 'ask|A lint, format or type-check configuration. Fix findings at their cause; change a rule only on purpose (CLAUDE.md).' ;;
	web/vite.config.ts)
		echo 'ask|The web build and test config, including the coverage thresholds. Lowering a threshold to pass is not a fix.' ;;
	backend/crates/gitprompt-server/tests/snapshots/*)
		echo "ask|API snapshots: regenerate with \`just snapshots\` and review the diff; never edit or accept them unread (CLAUDE.md)." ;;
	.claude/settings.json | .claude/settings.local.json | .claude/hooks/*)
		echo 'ask|The guardrails themselves (hooks and their settings). Approve only an intended change to how agent work is checked.' ;;
	.github/workflows/*)
		echo 'ask|CI: what every change must pass before it merges.' ;;
	justfile)
		echo 'ask|The justfile holds the checks CI and the hooks run (verify, lint, deps, arch). Approve if the change keeps them at least as strict.' ;;
	esac
}

# Text of an edit that touches lint levels in a Cargo manifest (`[workspace.lints]`, `[lints]`).
lint_section_edit() {
	printf '%s' "$1" | grep -qE '^\s*\[(workspace\.)?lints|^\s*[a-z_]+\s*=\s*(\{[^}]*level\s*=\s*)?"(allow|warn|deny|forbid)"'
}
